  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-field label {
  font-size: 0.85rem;
  font-weight: 600;
  color: #a0aec0;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.field-label-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.optional-badge {
  font-size: 0.72rem;
  font-weight: 500;
  color: #5a6478;
  background: #242838;
  border: 1px solid #2d3148;
  border-radius: 4px;
  padding: 1px 6px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.form-field input {
  width: 100%;
  padding: 0.65rem 0.9rem;
  background-color: #12141e;
  border: 1px solid #2d3148;
  border-radius: 8px;
  color: #e2e8f0;
  font-size: 0.95rem;
  font-family: inherit;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  outline: none;
}

.form-field input::placeholder {
  color: #3f4760;
}

.form-field input:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.18);
}

.form-field input.input-error {
  border-color: #ef4444;
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.15);
}

.helper-text {
  font-size: 0.78rem;
  color: #5a6478;
  margin-top: 0.1rem;
}

.submit-btn {
  margin-top: 0.5rem;
  padding: 0.75rem 1.5rem;
  background: linear-gradient(135deg, #6366f1, #818cf8);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: opacity 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 14px rgba(99, 102, 241, 0.35);
  letter-spacing: 0.01em;
}

.submit-btn:hover {
  opacity: 0.9;
  box-shadow: 0 6px 20px rgba(99, 102, 241, 0.45);
}

.submit-btn:active {
  transform: translateY(1px);
  box-shadow: 0 2px 8px rgba(99, 102, 241, 0.3);
}

.submit-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.success-banner {
  margin-top: 1.25rem;
  padding: 0.75rem 1rem;
  background: rgba(34, 197, 94, 0.1);
  border: 1px solid rgba(34, 197, 94, 0.3);
  border-radius: 8px;
  color: #4ade80;
  font-size: 0.875rem;
  text-align: center;
}
