function ContactForm() {
  const [fields, setFields] = useState({
    fullName: '',
    email: '',
    phone: '',
  });
  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [dirty, setDirty] = useState({});

  function validate(values) {
    const errs = {};
    if (!values.fullName.trim()) {
      errs.fullName = 'Full name is required.';
    }
    if (!values.email.trim()) {
      errs.email = 'Email address is required.';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
      errs.email = 'Please enter a valid email address.';
    }
    if (values.phone && !/^\+?[\d\s\-().]{7,20}$/.test(values.phone)) {
      errs.phone = 'Phone number format is invalid.';
    }
    return errs;
  }

  function handleChange(e) {
    const { name, value } = e.target;
    const updated = { ...fields, [name]: value };
    setFields(updated);
    if (dirty[name]) {
      const errs = validate(updated);
      setErrors(prev => ({ ...prev, [name]: errs[name] }));
    }
  }

  function handleBlur(e) {
    const { name } = e.target;
    setDirty(prev => ({ ...prev, [name]: true }));
    const errs = validate(fields);
    setErrors(prev => ({ ...prev, [name]: errs[name] }));
  }

  function handleSubmit(e) {
    e.preventDefault();
    const allDirty = { fullName: true, email: true, phone: true };
    setDirty(allDirty);
    const errs = validate(fields);
    setErrors(errs);
    if (Object.keys(errs).length === 0) {
      setSubmitted(true);
    }
  }

  if (submitted) {
    return (
      <div className="form-card">
        <div className="form-header">
          <h1>Support — Contact Us</h1>
        </div>
        <div className="success-banner">
          ✓ Your message has been received. We'll be in touch soon.
        </div>
      </div>
    );
  }

  return (
    <div className="form-card">
      <div className="form-header">
        <h1>Support — Contact Us</h1>
        <p>Fill out the form below and our team will get back to you shortly.</p>
      </div>

      <form className="contact-form" onSubmit={handleSubmit} noValidate>
        <FormField id="fullName" label="Full Name">
          <input
            id="fullName"
            name="fullName"
            type="text"
            value={fields.fullName}
            onChange={handleChange}
            onBlur={handleBlur}
            placeholder="Jane Smith"
            autoComplete="name"
            className={dirty.fullName && errors.fullName ? 'input-error' : ''}
          />
        </FormField>

        <FormField id="email" label="Email Address">
          <input
            id="email"
            name="email"
            type="email"
            value={fields.email}
            onChange={handleChange}
            onBlur={handleBlur}
            placeholder="jane@example.com"
            autoComplete="email"
            className={dirty.email && errors.email ? 'input-error' : ''}
          />
        </FormField>

        <FormField
          id="phone"
          label="Phone Number"
          optional
          helperText="Format: +1 (555) 000-0000 — include country code for international numbers."
        >
          <input
            id="phone"
            name="phone"
            type="tel"
            value={fields.phone}
            onChange={handleChange}
            onBlur={handleBlur}
            placeholder="+1 (555) 000-0000"
            autoComplete="tel"
            className={dirty.phone && errors.phone ? 'input-error' : ''}
          />
        </FormField>

        <button type="submit" className="submit-btn">
          Send Message
        </button>
      </form>
    </div>
  );
}

function App() {
  return (
    <div className="page-wrapper">
      <ContactForm />
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<App />);
